      local o = { string.format("%02X", x) }
      for _, a in ipairs(fieldAddrs) do o[#o + 1] = string.format("%02X", rd(a + x)) end
      all[#all + 1] = table.concat(o, " ")
    end
    oout:write("S " .. table.concat(all, " ") .. "\n")
  end
  out:write(string.format("%d %02X %02X %02X %02X %02X %02X %02X %02X %02X %02X %02X %02X %02X %02X %02X %02X %02X %02X %02X %02X\n", T,
